package main

import (
	"container/heap"
	"fmt"
)

type Node struct {
	x, y, step int
}

type PQ []Node

func (p PQ) Len() int            { return len(p) }
func (p PQ) Less(i, j int) bool  { return p[i].step < p[j].step }
func (p PQ) Swap(i, j int)       { p[i], p[j] = p[j], p[i] }
func (p *PQ) Push(x interface{}) { *p = append(*p, x.(Node)) }
func (p *PQ) Pop() interface{} {
	old := *p
	n := len(old)
	item := old[n-1]
	*p = old[:n-1]
	return item
}

var vis [110][110]int
var f = [4][2]int{{0, 1}, {1, 0}, {0, -1}, {-1, 0}}
var q PQ

func bfs(l, u, xi, yi int) int {
	e := Node{l, u, 0}
	heap.Push(&q, e)
	vis[e.x][e.y] = 1
	for q.Len() > 0 {
		e = heap.Pop(&q).(Node)
		if e.x == xi && e.y == yi {
			return e.step
		}
		for i := 0; i < 4; i++ {
			t := Node{e.x + f[i][0], e.y + f[i][1], e.step + 1}
			if t.x < 0 || t.y < 0 {
				continue
			}
			if vis[t.x][t.y] != 0 {
				continue
			}
			vis[t.x][t.y] = 1
			heap.Push(&q, t)
		}
	}
	return 0
}

func main() {
	var s string
	fmt.Scan(&s)
	length := len(s)
	x, y, xx, yy := 0, 0, 0, 0
	for i := 0; i < length; i++ {
		if s[i] == 'L' {
			y--
		}
		if s[i] == 'R' {
			y++
		}
		if s[i] == 'U' {
			x--
		}
		if s[i] == 'D' {
			x++
		}
		if x < xx {
			xx = x
		}
		if y < yy {
			yy = y
		}
	}
	xx, yy = -xx, -yy
	for i := 0; i < 110; i++ {
		for j := 0; j < 110; j++ {
			vis[i][j] = 1
		}
	}
	x, y = xx, yy
	for i := 0; i < length; i++ {
		if s[i] == 'L' {
			y--
		}
		if s[i] == 'R' {
			y++
		}
		if s[i] == 'U' {
			x--
		}
		if s[i] == 'D' {
			x++
		}
		vis[x][y] = 0
	}
	ans := bfs(xx, yy, x, y)

	if ans == length {
		fmt.Println("OK")
	} else {
		fmt.Println("BUG")
	}
}
